function parseCsv(text:string){
 const clean=text.replace(/^\uFEFF/,"");const first=clean.split(/\r?\n/,1)[0]||"";
 const delimiter=(first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length?";":",";
 const matrix:string[][]=[];let row:string[]=[];let cell="";let quoted=false;
 for(let i=0;i<clean.length;i++){const ch=clean[i];if(ch==='"'){if(quoted&&clean[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===delimiter&&!quoted){row.push(cell.trim());cell=""}else if((ch==="\n"||ch==="\r")&&!quoted){if(ch==="\r"&&clean[i+1]==="\n")i++;row.push(cell.trim());if(row.some(v=>v!==""))matrix.push(row);row=[];cell=""}else cell+=ch}
 row.push(cell.trim());if(row.some(v=>v!==""))matrix.push(row);
 if(matrix.length<2)throw new Error("O CSV precisa ter cabeçalho e pelo menos uma linha.");
 return {headers:matrix[0].map(h=>h.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]/g,"")),records:matrix.slice(1)};
}
function localDate(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-");}
function addMonthsClamped(dateKey:string,months:number){const [year,month,day]=dateKey.split("-").map(Number);const target=new Date(year,month-1+months,1);const lastDay=new Date(target.getFullYear(),target.getMonth()+1,0).getDate();return [target.getFullYear(),String(target.getMonth()+1).padStart(2,"0"),String(Math.min(day,lastDay)).padStart(2,"0")].join("-");}
function prospectIntelligence(p:Record<string,any>){
 const factors:string[]=[];let score=0;
 const employees=Number(p.employees||0);const devices=Number(p.notebook_demand||0);
 if(employees>=200){score+=25;factors.push("200+ funcionários (+25)")}else if(employees>=50){score+=20;factors.push("50–199 funcionários (+20)")}else if(employees>=10){score+=12;factors.push("10–49 funcionários (+12)")}else if(employees>0){score+=5;factors.push("Até 9 funcionários (+5)")}
 if(devices>=50){score+=30;factors.push("Demanda estimada de 50+ notebooks (+30)")}else if(devices>=20){score+=24;factors.push("Demanda estimada de 20–49 notebooks (+24)")}else if(devices>=5){score+=15;factors.push("Demanda estimada de 5–19 notebooks (+15)")}else if(devices>0){score+=6;factors.push("Demanda estimada de 1–4 notebooks (+6)")}
 if(["Tecnologia","BPO","Call center","Consultoria","Logística","Serviços financeiros"].includes(String(p.sector||""))){score+=15;factors.push("Setor com possível uso intensivo de TI (+15)")}else if(p.sector){score+=6;factors.push("Setor informado (+6)")}
 if(p.rental_interest==="Já aluga"){score+=20;factors.push("Já utiliza locação (+20)")}else if(p.rental_interest==="Alto"){score+=18;factors.push("Interesse alto declarado (+18)")}else if(p.rental_interest==="Médio"){score+=10;factors.push("Interesse médio declarado (+10)")}else if(p.rental_interest==="Baixo"){score+=2;factors.push("Interesse baixo declarado (+2)")}
 const contactable=Boolean(p.contact_email||p.phone||p.contact_person);
 if(contactable){score+=10;factors.push("Canal ou pessoa de contato informado (+10)")}
 const known=[p.employees,p.notebook_demand,p.sector,p.rental_interest,p.city,p.contact_person,(p.contact_email||p.phone)].filter(v=>v!==undefined&&v!==null&&String(v).trim()!=="").length;
 const completeness=Math.round(known/7*100);
 const missing=["employees","notebook_demand","sector","rental_interest","city"].filter(k=>!p[k]).map(k=>({employees:"número de funcionários",notebook_demand:"demanda de notebooks",sector:"setor",rental_interest:"interesse em locação",city:"cidade"}[k]));if(!p.contact_person&&!p.contact_email&&!p.phone)missing.push("canal ou pessoa de contato");
 const followup=String(p.next_followup||"").slice(0,10);const today=localDate();
 const followupState=!followup?"Sem retorno agendado":followup<today?"Follow-up atrasado":followup===today?"Contato para hoje":"Follow-up agendado";
 const interactions=Array.isArray(p.interactions)?p.interactions:[];const attempts=interactions.length;
 const lastInteraction=[...interactions].sort((a:any,b:any)=>String(b.date||b.created_at||"").localeCompare(String(a.date||a.created_at||"")))[0];
 const lastContact=String(lastInteraction?.date||p.last_contact_at||"").slice(0,10);
 const daysSinceContact=lastContact?Math.max(0,Math.floor((new Date(today+"T00:00:00").getTime()-new Date(lastContact+"T00:00:00").getTime())/86400000)):null;
 const lastOutcome=String(lastInteraction?.outcome||"");
 let cadenceStatus="Sem tentativa registrada";let recommendedAction="Pesquisar decisor e encontrar um canal de contato";let cadencePriority=0;
 if(attempts===0){cadencePriority=3}
 else if(["Interessado","Proposta solicitada","Reunião agendada","Retorno combinado"].includes(lastOutcome)){cadenceStatus="Sinal positivo";recommendedAction=!followup?"Registrar a próxima data de retorno e a ação combinada":lastOutcome==="Reunião agendada"?"Confirmar reunião e participantes":lastOutcome==="Proposta solicitada"?"Preparar e encaminhar proposta comercial":lastOutcome==="Retorno combinado"?"Cumprir o retorno combinado na data registrada":"Agendar conversa de qualificação";cadencePriority=4}
 else if(followup&&followup<=today){cadenceStatus=followup<today?"Retorno vencido":"Retorno para hoje";recommendedAction=String(lastInteraction?.next_action||p.next_action||"Executar follow-up combinado");cadencePriority=5}
 else if(lastOutcome==="Sem resposta"){cadenceStatus=daysSinceContact!==null&&daysSinceContact>=3?"Sem resposta há "+daysSinceContact+" dias":"Aguardando resposta";recommendedAction=daysSinceContact!==null&&daysSinceContact>=3?"Tentar um canal alternativo, sem repetir a mesma mensagem":"Aguardar o prazo combinado";cadencePriority=daysSinceContact!==null&&daysSinceContact>=3?3:1}
 else if(lastOutcome==="Sem interesse"){cadenceStatus="Sem interesse declarado";recommendedAction="Respeitar a decisão e não insistir";cadencePriority=-1}
 else if(daysSinceContact!==null&&daysSinceContact>=7){cadenceStatus="Contato parado há "+daysSinceContact+" dias";recommendedAction="Retomar com contexto e uma pergunta objetiva";cadencePriority=3}
 else if(attempts>0){cadenceStatus="Em acompanhamento";recommendedAction=String(lastInteraction?.next_action||p.next_action||"Definir próximo passo com o contato");cadencePriority=2}
 const stage=String(p.prospect_stage||"Novo lead");const tier=score>=70?"A":score>=40?"B":"C";
 return {score:Math.min(score,100),factors,completeness,missing,followup,followupState,tier,stage,attempts,lastContact,daysSinceContact,lastOutcome,cadenceStatus,recommendedAction,cadencePriority};
}
function prospectScore(p:Record<string,any>){return prospectIntelligence(p).score;}
